import{_ as r,C as i,o as d,c,j as e,a,E as n,a6 as l}from"./chunks/framework.CD0vXS2f.js";const b=JSON.parse('{"title":"04 · Deterministic Acceptance Contracts vs. Advisory LLM Judges","description":"Structuring non-flaky CI/CD evaluation pipelines for tool-using and RAG agents—separating hard deterministic release gates from advisory LLM-as-judge quality scoring.","frontmatter":{"title":"04 · Deterministic Acceptance Contracts vs. Advisory LLM Judges","description":"Structuring non-flaky CI/CD evaluation pipelines for tool-using and RAG agents—separating hard deterministic release gates from advisory LLM-as-judge quality scoring."},"headers":[],"relativePath":"playbooks/agentic-rag-evals/04-deterministic-eval-contracts.md","filePath":"playbooks/agentic-rag-evals/04-deterministic-eval-contracts.md","lastUpdated":1795642852816,"verifiedStamp":"2026-11-25 13:40 PST"}'),p={name:"playbooks/agentic-rag-evals/04-deterministic-eval-contracts.md"};function u(h,t,g,f,m,v){const o=i("PlaybookMeta"),s=i("PageBrief");return d(),c("div",null,[t[0]||(t[0]=e("h1",{id:"_04-·-deterministic-acceptance-contracts-vs-advisory-llm-judges",tabindex:"-1"},[a("04 · Deterministic Acceptance Contracts vs. Advisory LLM Judges "),e("a",{class:"header-anchor",href:"#_04-·-deterministic-acceptance-contracts-vs-advisory-llm-judges","aria-label":'Permalink to "04 · Deterministic Acceptance Contracts vs. Advisory LLM Judges"'},"​")],-1)),n(o,{track:"04 · Sandboxed Agentic Harness, Foundry IQ RAG & 7-Layer Evals",verified:"2026-11-19 22:12 PST",status:"Live v2.0",studioHref:"/studio/#agent-eval",studioLabel:"Eval Contract Builder →",kitHref:"/papers/engineering-kits#agent-gate",kitLabel:"agent_release_gate.py →"}),n(s,{stage:"validate",readTime:"4 min read",problem:"Gating pull requests solely on LLM-as-judge 1–5 rubric scores introduces non-deterministic CI flakiness, judge prompt-injection blind spots, and high PR latency.",takeaway:"Enforce the Golden Separation Rule: Deterministic checks gate merges; calibrated LLM judges score semantic quality trends and flag edge cases for human review.",csaUse:"Adopt the two-tier evaluation matrix below and wire agent_release_gate.py into GitHub Actions / Azure Pipelines."}),t[1]||(t[1]=e("h2",{id:"_1-the-golden-rule-deterministic-gates-block-llm-judges-advise-arch",tabindex:"-1"},[a("1. The Golden Rule: Deterministic Gates Block; LLM Judges Advise "),e("code",null,"[Arch]"),a(),e("a",{class:"header-anchor",href:"#_1-the-golden-rule-deterministic-gates-block-llm-judges-advise-arch","aria-label":'Permalink to "1. The Golden Rule: Deterministic Gates Block; LLM Judges Advise `[Arch]`"'},"​")],-1)),t[2]||(t[2]=e("div",{class:"arch-diagram"},[e("svg",{viewBox:"0 0 760 154",role:"img","aria-labelledby":"pb4-ev-title pb4-ev-desc","font-family":"Segoe UI, Inter, -apple-system, sans-serif"},[e("title",{id:"pb4-ev-title"},"Two-Tier Agent Evaluation Pipeline: Deterministic Blockers vs Calibrated Judges"),e("desc",{id:"pb4-ev-desc"},"Shows Agent Golden Run Evidence JSONL flowing first into Tier A Deterministic Contract Verifier (Hard CI Merge Blocker checking AST lint, tool schema, citation IDs, forbidden actions, and Pass-2 cache hit) and second into Tier B Foundry / DeepEval / Waza Calibrated Judges (Release Scorecard tracking groundedness, completeness, and safety parity)."),e("defs",null,[e("marker",{id:"ev-arr",markerWidth:"8",markerHeight:"8",refX:"7",refY:"4",orient:"auto"},[e("path",{d:"M0 0 L8 4 L0 8Z",fill:"#0f766e"})])]),e("rect",{x:"8",y:"20",width:"182",height:"94",rx:"6",fill:"#edf3fb",stroke:"#5b87b2","stroke-width":"1.4"}),e("text",{x:"16",y:"39","font-size":"9.1","font-weight":"700",fill:"#183e62"},"1. Golden Corpus Execution"),e("text",{x:"16",y:"55","font-size":"8.1",fill:"#334e68"},"• 50–200 sanitized cases"),e("text",{x:"16",y:"69","font-size":"8.1",fill:"#334e68"},"• Waza skill trajectories"),e("text",{x:"16",y:"83","font-size":"8.1",fill:"#334e68"},"• Emits trace.jsonl evidence"),e("text",{x:"16",y:"101","font-size":"7.8","font-weight":"700",fill:"#1d4ed8"},"[2-Pass Cache + Tool Log]"),e("path",{d:"M190 67 H218",stroke:"#0f766e","stroke-width":"1.8","marker-end":"url(#ev-arr)"}),e("rect",{x:"222",y:"20",width:"256",height:"94",rx:"6",fill:"#eaf7f5",stroke:"#0f766e","stroke-width":"1.5"}),e("text",{x:"232",y:"39","font-size":"9.2","font-weight":"700",fill:"#115e59"},"2. Tier A · Deterministic Gate (BLOCKS CI)"),e("text",{x:"232",y:"55","font-size":"8.1",fill:"#334e68"},"• PCR001–006 static prefix AST lint"),e("text",{x:"232",y:"69","font-size":"8.1",fill:"#334e68"},"• Citation IDs exist in retrieved docs"),e("text",{x:"232",y:"83","font-size":"8.1",fill:"#334e68"},"• Zero forbidden tools · Pass-2 cached ≥1024"),e("text",{x:"232",y:"101","font-size":"7.8","font-weight":"700",fill:"#0f766e"},"[100% Reproducible · Sub-Second CLI]"),e("path",{d:"M478 67 H506",stroke:"#0f766e","stroke-width":"1.8","marker-end":"url(#ev-arr)"}),e("rect",{x:"510",y:"20",width:"242",height:"94",rx:"6",fill:"#fff7eb",stroke:"#d97706","stroke-width":"1.4"}),e("text",{x:"520",y:"39","font-size":"9.2","font-weight":"700",fill:"#92400e"},"3. Tier B · Calibrated LLM Judges"),e("text",{x:"520",y:"55","font-size":"8.1",fill:"#92400e"},"• Foundry Evals / DeepEval rubrics"),e("text",{x:"520",y:"69","font-size":"8.1",fill:"#92400e"},"• Groundedness, Relevance & Safety"),e("text",{x:"520",y:"83","font-size":"8.1",fill:"#92400e"},"• Model-upgrade delta (≤2% drop)"),e("text",{x:"520",y:"101","font-size":"7.8","font-weight":"700",fill:"#b45309"},"[Release Advisory & Trend Gate]"),e("text",{x:"10",y:"138","font-size":"8.3",fill:"#526c80"},"Separating deterministic contract invariants from statistical rubric judges eliminates CI flakiness while catching subtle quality drift.")])],-1)),t[3]||(t[3]=l('<hr><h2 id="_2-five-layer-agent-verification-matrix" tabindex="-1">2. Five-Layer Agent Verification Matrix <a class="header-anchor" href="#_2-five-layer-agent-verification-matrix" aria-label="Permalink to &quot;2. Five-Layer Agent Verification Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Verification Layer</th><th style="text-align:left;">Tool / Mechanism</th><th style="text-align:left;">Hard CI Gate vs. Release Scorecard</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. Static Prompt &amp; Prefix Lint</strong></td><td style="text-align:left;"><a href="/enterprise-azure-ai-hub/papers/engineering-kits#pcr-linter"><code>pcr_lint.py</code></a> (<code>PCR001–PCR006</code>)</td><td style="text-align:left;"><strong>Hard PR Blocker</strong> (<code>0</code> violations).</td></tr><tr><td style="text-align:left;"><strong>2. Skill Routing &amp; Trajectory Evals</strong></td><td style="text-align:left;"><a href="https://github.com/microsoft/waza" target="_blank" rel="noreferrer"><code>microsoft/waza</code></a> skill evaluation tasks</td><td style="text-align:left;"><strong>Hard PR Blocker</strong> on expected skill invocation &amp; required tool sequence.</td></tr><tr><td style="text-align:left;"><strong>3. Offline Trace Contract Verification</strong></td><td style="text-align:left;"><a href="/enterprise-azure-ai-hub/papers/engineering-kits#agent-gate"><code>agent_release_gate.py</code></a> (<code>ARG001–ARG007</code>) + <a href="/enterprise-azure-ai-hub/studio/#agent-eval"><code>AgentEvalBuilder</code></a></td><td style="text-align:left;"><strong>Hard PR / Release Blocker</strong> verifying JSON schema compliance (<code>ARG001</code>), required/forbidden tool governance (<code>ARG002</code>), <code>100%</code> resolved citation IDs (<code>ARG003</code>), Pass-2 <code>cached_tokens ≥ 1,024</code> (<code>ARG004</code>), p95 turn latency ceiling (<code>ARG005</code>), Foundry IQ ACL security trimming <code>acl_trimmed != false</code> (<code>ARG006</code>), and metadata-only OTel privacy <code>raw_prompt_logged == false</code> (<code>ARG007</code>).</td></tr><tr><td style="text-align:left;"><strong>4. Semantic Quality &amp; Groundedness</strong></td><td style="text-align:left;">Azure AI Foundry Evaluation SDK (<code>GroundednessEvaluator</code>, <code>RelevanceEvaluator</code>, <code>TaskAdherenceEvaluator</code>) <span class="ev-badge ev-m">[M]</span></td><td style="text-align:left;"><strong>Release Cutover Gate</strong> on nightly / pre-prod golden suite (<code>≤2%</code> score regression across model snapshot upgrades) <span class="ev-badge ev-agree">[Agree]</span>.</td></tr><tr><td style="text-align:left;"><strong>5. Multi-Turn Adversarial &amp; Safety Red-Teaming</strong></td><td style="text-align:left;">Azure AI Content Safety + PyRIT / multi-turn safety baselines (<code>Indirect Prompt Injection</code>, <code>Cross-Tenant Probe</code>) <span class="ev-badge ev-m">[M]</span></td><td style="text-align:left;"><strong>Mandatory Pre-Cutover Sign-Off</strong> (<code>0</code> critical jailbreaks or unauthorized tool invocations).</td></tr></tbody></table><h3 id="fail-closed-trace-evidence-arg001" tabindex="-1">Fail-Closed Trace Evidence (<code>ARG001</code>) <a class="header-anchor" href="#fail-closed-trace-evidence-arg001" aria-label="Permalink to &quot;Fail-Closed Trace Evidence (`ARG001`)&quot;">​</a></h3><p><span class="ev-badge ev-arch">[Arch]</span> Every non-blank JSONL line must be a complete turn object. Missing evidence must block release rather than silently defaulting token counts to zero or omitting a turn from the latency sample.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Required field</th><th style="text-align:left;">Trace contract</th></tr></thead><tbody><tr><td style="text-align:left;"><code>case_id</code>, <code>status</code></td><td style="text-align:left;">Non-empty strings; terminal <code>status</code> must be <code>&quot;ok&quot;</code>.</td></tr><tr><td style="text-align:left;"><code>assistant_response</code></td><td style="text-align:left;">String; an empty answer is structurally valid, not proof of semantic quality.</td></tr><tr><td style="text-align:left;"><code>tools_called</code>, <code>retrieved_doc_ids</code></td><td style="text-align:left;">Arrays of non-empty strings; tool names must not have leading/trailing whitespace. Use <code>[]</code> when no tools/documents were involved.</td></tr><tr><td style="text-align:left;"><code>pass_number</code></td><td style="text-align:left;">Integer <code>&gt;=1</code>; booleans, numeric strings, and fractional values are rejected.</td></tr><tr><td style="text-align:left;"><code>input_tokens</code>, <code>cached_tokens</code></td><td style="text-align:left;">Integers <code>&gt;=0</code>, with <code>cached_tokens &lt;= input_tokens</code>.</td></tr><tr><td style="text-align:left;"><code>duration_ms</code></td><td style="text-align:left;">Finite number <code>&gt;=0</code> for every turn; missing values, <code>NaN</code>, and infinities are rejected.</td></tr><tr><td style="text-align:left;"><code>acl_trimmed</code></td><td style="text-align:left;">Explicit boolean required on non-empty retrievals when ACL enforcement is enabled; <code>false</code> triggers <code>ARG006</code>.</td></tr><tr><td style="text-align:left;"><code>raw_prompt_logged</code></td><td style="text-align:left;">Explicit boolean required when metadata-only telemetry enforcement is enabled; <code>true</code> triggers <code>ARG007</code>.</td></tr><tr><td style="text-align:left;"><code>otel_capture_message_content</code></td><td style="text-align:left;">Optional; must be a boolean when present and triggers <code>ARG007</code> when <code>true</code> under metadata-only enforcement.</td></tr></tbody></table><p>All supplied ACL/privacy flags must be booleans even when their enforcement is disabled. Structurally invalid turns produce <code>ARG001</code> failures and exit <code>1</code> (including under <code>--json</code>); malformed JSON produces a line-numbered <code>ARG001</code> error on stderr and exit <code>2</code>. Diagnostics for malformed evidence identify the row/field without echoing raw turn content. The zero-dependency <code>python3 docs/public/kits/agent_release_gate.py --self-test</code> regression suite is included in <code>npm run verify</code>.</p><p>Missing/unreadable trace files, directory inputs, and invalid UTF-8 also exit <code>2</code> with a sanitized <code>ARG001</code> stderr diagnostic and no stdout in text or <code>--json</code> mode. The CLI reads the complete file before evaluating any turns, so a valid prefix followed by undecodable bytes cannot produce a partial pass. Read-error diagnostics omit paths, file content, and operating-system exception details; self-tests cover file/encoding failures and injected permission/I/O errors without relying on platform-specific file permissions <span class="ev-badge ev-arch">[Arch]</span>.</p><h3 id="metadata-only-failure-reports" tabindex="-1">Metadata-Only Failure Reports <a class="header-anchor" href="#metadata-only-failure-reports" aria-label="Permalink to &quot;Metadata-Only Failure Reports&quot;">​</a></h3><p><span class="ev-badge ev-arch">[Arch]</span> Every per-turn finding identifies the non-blank record ordinal (<code>row-N</code>), never the case ID, reported status text, tool names (including required tools from the contract), citation IDs, or answer content. Those strings can carry sensitive identifiers or terminal control characters; the verifier must not copy them into CI logs while enforcing metadata-only telemetry. Correlate the row with the original trace and approved contract in access-controlled storage. The trace-wide <code>ARG005</code> finding still reports the numeric p95 and budget; cache findings retain numeric counts.</p><p>Rule IDs, finding counts, exact tool/citation matching, acceptance decisions, exit codes, and JSON <code>record_count</code> are unchanged; consumers parsing the old value-bearing message text must switch to rule IDs and row ordinals. Offline text/JSON regressions exercise all seven rules, malformed and missing citations, synthetic private strings, embedded newline/ANSI control characters, and escaped unpaired Unicode surrogates without leaking values or causing output-encoding failures. Clean evidence with the same case identifier still passes. This local reporting policy does not redact the source trace or authenticate its contents; retain trusted provenance and restricted artifact access.</p><h3 id="unique-case-pass-evidence" tabindex="-1">Unique Case/Pass Evidence (<code>ARG001</code>) <a class="header-anchor" href="#unique-case-pass-evidence" aria-label="Permalink to &quot;Unique Case/Pass Evidence (`ARG001`) {#unique-case-pass-evidence}&quot;">​</a></h3><p><span class="ev-badge ev-arch">[Arch]</span> Each structurally valid <code>(case_id, pass_number)</code> pair must occur only once per trace file. Repeated evidence can inflate the latency sample: one slow turn followed by twenty copies of a fast turn can put the slow turn outside the nearest-rank p95. Identical copies and conflicting records with the same pair both produce <code>ARG001</code> and exit <code>1</code>, including under <code>--json</code>; no duplicate-containing trace can pass.</p><p>Pair comparison uses exact, case-sensitive decoded strings and integer pass numbers, without trimming or coercion. The same case may appear in distinct passes, and different cases may share a pass number. Assign distinct case/turn identifiers within a pass; if a harness emits multiple turns or retries for one scenario, encode the turn/attempt in <code>case_id</code>. Diagnostics report the duplicate&#39;s record ordinal and the first occurrence, not the identifier or response. Record ordinals count non-blank JSONL records, not physical lines.</p><p>Case IDs must not have leading or trailing whitespace, including tabs, newlines, and Unicode whitespace. Adding different amounts of whitespace to copied fast turns must not evade uniqueness and dilute p95 latency. Padded trace IDs produce field-only <code>ARG001</code> findings and exit <code>1</code>; they do not satisfy inventory coverage or enter the latency sample. Padded IDs in <code>expected_case_passes</code> exit <code>2</code> before evidence is read, without echoing identifiers. The verifier rejects rather than trims; internal spaces, punctuation, case-sensitive identities, and distinct passes remain supported. Correct the harness and independently approved inventory instead of editing evidence to force a pass. Offline text/JSON regressions cover whitespace aliases, latency padding, missing inventory coverage, configuration precedence, and valid identities. This is a local identity-integrity policy, not an Azure case-name grammar or proof of execution authenticity <span class="ev-badge ev-arch">[Arch]</span>.</p><p>Duplicates remain subject to all other checks rather than being silently discarded; JSON <code>record_count</code> still reports every parsed record. Offline regressions cover separated/repeated duplicates, conflicting durations, p95 padding, text/JSON failures, preserved tool/citation/cache/ACL/privacy findings, and distinct-pass compatibility. This is a local evidence-integrity rule, not an Azure service schema or proof of provenance; uniqueness alone cannot enforce corpus completeness or detect distinct fabricated identifiers.</p><h3 id="expected-golden-run-inventory-arg001" tabindex="-1">Expected Golden-Run Inventory (<code>ARG001</code>) <a class="header-anchor" href="#expected-golden-run-inventory-arg001" aria-label="Permalink to &quot;Expected Golden-Run Inventory (`ARG001`)&quot;">​</a></h3><p><span class="ev-badge ev-arch">[Arch]</span> For release sign-off, add an independently approved <code>expected_case_passes</code> inventory to the acceptance contract. Without an inventory, one clean turn can pass even if the harness silently omitted the rest of the golden run. With an inventory, every expected pair must have exactly one structurally valid record, and no unexpected pair may appear. This also blocks latency-sample padding with additional distinct case identifiers.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expected_case_passes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;case_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;grounding-check&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;pass_number&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;case_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;grounding-check&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;pass_number&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The optional field must be a non-empty array of objects containing <strong>only</strong> a non-empty string <code>case_id</code> without leading/trailing whitespace and an integer <code>pass_number &gt;= 1</code>. Boolean, fractional, duplicate, padded, and malformed entries are invalid configuration: exit <code>2</code> before trace evidence is read, with no stdout in text or <code>--json</code> mode. Omit the field for existing unconstrained behavior; <code>null</code> and <code>[]</code> do not silently disable an inventory. Matching uses the same exact, case-sensitive identifiers as uniqueness, without trimming/coercion, and record order is irrelevant.</p><p>Missing or unexpected pairs produce <code>ARG001</code> and exit <code>1</code>; structurally invalid records do not satisfy inventory coverage. Diagnostics report only a missing-pair count or unexpected record ordinal, never inventory identifiers. All existing checks still apply, and JSON <code>record_count</code> includes every parsed record. Offline self-tests cover complete/reordered runs, omissions, unexpected identifiers, duplicates, malformed configuration, and distinct-ID latency padding.</p><p>Maintain the inventory separately from the trace under review; generating it from that trace would simply bless omissions. Studio exports remain compatible but do not populate this optional inventory or simulate its coverage. This local completeness policy does not prove execution authenticity, semantic quality, or that the approved corpus covers every production risk.</p><h3 id="repeat-pass-cache-evidence" tabindex="-1">Opt-In Repeat-Pass Cache Evidence (<code>ARG004</code>) <a class="header-anchor" href="#repeat-pass-cache-evidence" aria-label="Permalink to &quot;Opt-In Repeat-Pass Cache Evidence (`ARG004`) {#repeat-pass-cache-evidence}&quot;">​</a></h3><p>An otherwise clean trace containing only cold passes or inputs below the configured cache threshold does not exercise <code>ARG004</code>. For cache-readiness sign-off, add <code>&quot;require_pass2_cache_evidence&quot;: true</code> to the acceptance contract. The trace must contain at least one structurally valid record with <code>pass_number &gt;= 2</code> and <code>input_tokens &gt;= min_pass2_cached_tokens</code>; every eligible record still requires <code>cached_tokens &gt;= min_pass2_cached_tokens</code>. If none exists, the gate emits a trace-wide <code>ARG004</code> finding and exits <code>1</code> in text or <code>--json</code> mode, without echoing case IDs or response content <span class="ev-badge ev-arch">[Arch]</span>.</p><p>The optional field accepts only a JSON boolean; invalid types exit <code>2</code> before evidence is read. Omitted or <code>false</code> preserves existing contracts and Studio exports. The default eligibility threshold remains <code>1024</code>; raising it above every repeat turn&#39;s input count now blocks sign-off when this option is enabled rather than silently skipping cache evidence. Short turns and cold passes remain allowed alongside an eligible repeat turn. Invalid records do not satisfy the requirement, and other schema, tool, citation, latency, ACL, and privacy failures still block release.</p><p>This local evidence-presence policy does not establish a shared prefix, real execution, cache eligibility for a particular model, or complete two-pass coverage of every case. Pair it with an independently approved <code>expected_case_passes</code> inventory and trusted harness telemetry; use separate contracts for intentionally cold-only or short-input corpora. Studio does not populate or simulate this optional control. Offline regressions cover cold-only and short-only traces, raised thresholds, inclusive boundaries, later passes, malformed records, existing cache-miss and latency failures, boolean validation precedence, text/JSON exit codes, and recovery with eligible cached evidence <span class="ev-badge ev-arch">[Arch]</span>.</p><h3 id="unambiguous-json-inputs" tabindex="-1">Unambiguous JSON Inputs <a class="header-anchor" href="#unambiguous-json-inputs" aria-label="Permalink to &quot;Unambiguous JSON Inputs&quot;">​</a></h3><p>JSONL framing preserves literal Unicode next-line (<code>U+0085</code>), line-separator (<code>U+2028</code>), and paragraph-separator (<code>U+2029</code>) characters inside JSON strings instead of splitting answers or metadata into extra records. LF and CRLF exports, blank lines, escaped newlines, and a final record without a trailing newline remain supported. These Unicode characters and other non-newline text separators between JSON objects do <strong>not</strong> create separate records: malformed framing exits <code>2</code> with a physical-line <code>ARG001</code> stderr diagnostic, no stdout or partial pass in text and <code>--json</code> modes. Valid Unicode answers still undergo every existing release check, without being echoed into diagnostics. Offline regressions cover passing/failing Unicode records, preserved record counts, and malformed separators after valid evidence. This is a local parser-integrity policy, not an Azure trace schema or evidence-authenticity guarantee <span class="ev-badge ev-arch">[Arch]</span>.</p><p><span class="ev-badge ev-arch">[Arch]</span> Trace records and acceptance-contract files must use unique member names within <strong>every JSON object</strong>, including optional nested metadata. The CLI rejects duplicates before schema validation or evaluation instead of silently keeping the last value: <code>&quot;raw_prompt_logged&quot;: true</code> followed by <code>&quot;raw_prompt_logged&quot;: false</code> must not turn failing evidence into a pass. Identical duplicate values are also rejected, and JSON escape sequences are decoded before comparing names.</p><p>Duplicate trace members produce a line-numbered <code>ARG001</code> stderr diagnostic; duplicate contract members produce an invalid-acceptance-contract stderr diagnostic. Both exit <code>2</code> with no stdout, including under <code>--json</code>, without echoing member names or values. Reusing a name in separate objects or separate JSONL records remains valid. This is a local input-integrity rule, not an Azure service requirement or proof that exported evidence is authentic; preserve trusted trace provenance.</p><p>JSON exceeding the Python parser&#39;s nesting limit also exits <code>2</code> without a traceback or stdout in text and <code>--json</code> modes. Trace diagnostics identify the physical JSONL line (<code>ARG001</code>); contract diagnostics identify invalid acceptance configuration before trace evidence is read. Neither echoes nested member names, values, or exception details, and a valid trace prefix cannot produce a partial pass. Offline CLI regressions cover deeply nested arrays and objects in both inputs, plus ordinary nested metadata that remains valid. This handles parser recursion failures, not a fixed portable depth budget, file-size limit, memory-exhaustion guard, or evidence-authenticity check <span class="ev-badge ev-arch">[Arch]</span>.</p><p>Unquoted <code>NaN</code>, <code>Infinity</code>, and <code>-Infinity</code> anywhere in either input also exit <code>2</code>, including otherwise ignored nested metadata. A valid trace prefix cannot produce a partial pass. Trace diagnostics identify the physical JSONL line (<code>ARG001</code>); invalid contracts are rejected before trace evidence is read, even when that trace is missing. Neither text nor <code>--json</code> mode emits stdout or echoes the constant, field, path, or nested values <span class="ev-badge ev-arch">[Arch]</span>.</p><p>Quoted strings such as <code>&quot;NaN&quot;</code>, ordinary nested metadata, and standard JSON numbers remain supported. This local parsing policy does not impose a finite numeric range on informational metadata, validate its semantics, or authenticate evidence; existing finite latency checks still apply to enforcement fields. Offline regressions cover all three constants as top-level values, numeric fields, and nested objects/arrays in both inputs, configuration precedence, sanitized failures, and recovery. They run through <code>node scripts/run-python.mjs docs/public/kits/agent_release_gate.py --self-test</code> in <code>npm run verify</code>, without live Azure access <span class="ev-badge ev-arch">[Arch]</span>.</p><h3 id="fail-closed-citation-syntax-arg003" tabindex="-1">Fail-Closed Citation Syntax (<code>ARG003</code>) <a class="header-anchor" href="#fail-closed-citation-syntax-arg003" aria-label="Permalink to &quot;Fail-Closed Citation Syntax (`ARG003`)&quot;">​</a></h3><p><span class="ev-badge ev-arch">[Arch]</span> Every literal, case-sensitive <code>[cite:</code> opener in <code>assistant_response</code> must form a complete <code>[cite:ID]</code> marker. IDs must contain one or more ASCII letters, digits, or <code>_ . : # -</code> characters (no spaces). Empty IDs, whitespace, unsupported characters, nested markers, and missing closing brackets produce <code>ARG003</code> and exit <code>1</code>, including under <code>--json</code>, rather than disappearing from the resolution check. Malformed-marker diagnostics do not echo the answer or malformed ID; well-formed IDs still must exactly match <code>retrieved_doc_ids</code>.</p><p>Repeated valid markers remain allowed. Answers without citation markers remain structurally valid: this gate verifies marker syntax and ID resolution, <strong>not</strong> citation completeness, source relevance, or whether the cited document supports the answer. Keep those semantic checks in the calibrated quality review above.</p><h3 id="opt-in-citation-presence-arg003" tabindex="-1">Opt-In Citation Presence (<code>ARG003</code>) <a class="header-anchor" href="#opt-in-citation-presence-arg003" aria-label="Permalink to &quot;Opt-In Citation Presence (`ARG003`)&quot;">​</a></h3><p><span class="ev-badge ev-arch">[Arch]</span> For a grounded-answer corpus, add <code>&quot;require_citations&quot;: true</code> to the acceptance contract. Every structurally valid turn must then contain at least one well-formed <code>[cite:ID]</code> marker, and all markers remain subject to the existing syntax and retrieved-ID resolution checks. Empty answers, uncited answers (even with retrieved documents), and malformed-only markers cannot pass. Missing citations produce a row-numbered <code>ARG003</code> finding and exit <code>1</code> in text or <code>--json</code> mode without echoing the answer.</p><p>The field accepts only a JSON boolean; invalid types exit <code>2</code> before evidence is read. Omitted or <code>false</code> preserves existing behavior, including Studio exports. Studio does not currently populate or simulate this optional control. Use separate contracts for corpora containing intentionally uncited refusals or tool-only turns: when enabled, the requirement applies to every valid turn, not only turns reporting retrievals. A resolved marker proves neither that the source supports the answer nor that all claims are cited; retain semantic review and trusted trace provenance. Offline regressions cover empty/uncited turns, malformed/unresolved markers, successful cited turns, default compatibility, and configuration-validation precedence.</p><h3 id="fail-closed-acceptance-configuration" tabindex="-1">Fail-Closed Acceptance Configuration <a class="header-anchor" href="#fail-closed-acceptance-configuration" aria-label="Permalink to &quot;Fail-Closed Acceptance Configuration&quot;">​</a></h3><p><span class="ev-badge ev-arch">[Arch]</span> The CLI validates acceptance configuration before reading trace evidence, without coercing strings, booleans, or fractional token thresholds. Invalid configuration exits <code>2</code> with a field-specific stderr diagnostic and no success-shaped JSON output, including under <code>--json</code>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Contract field</th><th style="text-align:left;">Accepted configuration</th></tr></thead><tbody><tr><td style="text-align:left;"><code>max_p95_ms</code></td><td style="text-align:left;">Finite number <code>&gt;0</code>; numeric strings, booleans, <code>NaN</code>, and infinities are rejected.</td></tr><tr><td style="text-align:left;"><code>min_pass2_cached_tokens</code></td><td style="text-align:left;">Integer <code>&gt;0</code>; no strings, booleans, or fractional values.</td></tr><tr><td style="text-align:left;"><code>required_tools</code>, <code>forbidden_tools</code></td><td style="text-align:left;">Arrays of non-empty strings without leading/trailing whitespace, not a single string; <code>[]</code> explicitly disables that list.</td></tr><tr><td style="text-align:left;"><code>require_acl_trimming</code>, <code>forbid_raw_prompt_logging</code></td><td style="text-align:left;">Explicit JSON booleans; <code>&quot;false&quot;</code>, <code>0</code>, and <code>null</code> are invalid.</td></tr><tr><td style="text-align:left;"><code>require_citations</code></td><td style="text-align:left;">Optional JSON boolean, default <code>false</code>; <code>true</code> requires at least one inline citation on every valid turn.</td></tr><tr><td style="text-align:left;"><code>require_pass2_cache_evidence</code></td><td style="text-align:left;">Optional JSON boolean, default <code>false</code>; <code>true</code> requires at least one structurally valid repeat turn meeting the configured input-token threshold.</td></tr><tr><td style="text-align:left;"><code>expected_case_passes</code></td><td style="text-align:left;">Optional non-empty array of unique <code>{ &quot;case_id&quot;: &quot;...&quot;, &quot;pass_number&quot;: 1 }</code> objects; see the golden-run inventory above.</td></tr></tbody></table><p>The <a href="/enterprise-azure-ai-hub/studio/#agent-eval">Studio contract builder</a> also rejects blank/string, non-finite, and non-positive thresholds before displaying or copying contract JSON or the combined ACA/gate CLI. Invalid configuration shows linked field errors and a simulated <code>BLOCKED (Exit 2)</code>, never a passing trace result; direct copy-handler calls are guarded too. Positive fractional latency budgets remain valid. Token thresholds must additionally be safe JavaScript integers so the exported JSON preserves their exact value; this browser representation boundary is not an Azure service limit. The default <code>15000</code> ms / <code>1024</code> tokens is unchanged. The cache-miss scenario applies <code>ARG004</code> only when its <code>4800</code> input tokens meet the configured threshold, matching the kit; a higher threshold skips that scenario&#39;s cache check rather than certifying cache parity. Deterministic Vue interaction regressions run in <code>npm run verify</code>. Session-pool sizing and other trace checks remain separate; this illustrative simulation does not evaluate actual evidence or certify an appropriate SLO <span class="ev-badge ev-arch">[Arch]</span>.</p><p>The contract root must be a JSON object. Omitted fields retain existing defaults (<code>15000</code> ms, <code>1024</code> cached tokens, the built-in forbidden tools, no required tools, and both ACL/privacy controls enabled); Studio metadata such as <code>contract_version</code> and <code>track</code> remains compatible. CLI-only <code>--max-p95-ms</code> and <code>--min-cached-tokens</code> obey the same positive-threshold rules; <code>--contract</code> continues to take precedence over those flags. Missing/unreadable files, invalid UTF-8, and malformed JSON also exit <code>2</code> without a traceback. These checks validate configuration integrity, not whether an explicitly chosen threshold is an appropriate release SLO <span class="ev-badge ev-agree">[Agree]</span>.</p><p>Tool names use exact, case-sensitive matching. A padded denylist entry such as <code>&quot;raw_shell_root &quot;</code> must not silently permit <code>&quot;raw_shell_root&quot;</code>, and padded trace names must not bypass the configured denylist. The CLI rejects leading/trailing whitespace (including tabs, newlines, and non-breaking spaces) in either contract tool list with exit <code>2</code> before reading evidence; padded <code>tools_called</code> entries produce <code>ARG001</code> and exit <code>1</code>. It does not silently trim names. Diagnostics identify only the field/record, not the rejected name, and text/JSON regressions cover configuration precedence and corrected denylist enforcement. Empty lists, ordinary names, punctuation, and case-sensitive matching remain supported. This is a local identifier-integrity rule, not an Azure tool-name grammar or proof that a trace reports the actual tool invoked <span class="ev-badge ev-arch">[Arch]</span>.</p><p>The effective <code>required_tools</code> and <code>forbidden_tools</code> lists must also be disjoint: no trace can satisfy a policy that both requires and forbids the same exact tool. This includes conflicts with the built-in forbidden tools when <code>forbidden_tools</code> is omitted. Contradictions exit <code>2</code> before trace evidence is read, with a field-only stderr diagnostic and no stdout in text or <code>--json</code> mode; tool names are not echoed. An explicit <code>forbidden_tools: []</code> still disables the denylist, and differently cased tool names remain distinct. Offline regressions cover explicit/default conflicts, configuration precedence over missing evidence, case-sensitive compatibility, and empty-list overrides. This is a local configuration-consistency check, not an expansion of the denylist or proof that a chosen tool policy is safe <span class="ev-badge ev-arch">[Arch]</span>.</p><p>Unknown top-level fields are rejected before trace evidence is read: misspellings such as <code>required_tool</code> or <code>max_p95_mss</code> must not silently substitute default governance or latency settings. Only the enforcement fields above and the informational fields <code>contract_version</code>, <code>track</code>, and <code>metadata</code> are accepted. Informational fields do not configure enforcement; nested metadata remains extensible (and still obeys the unique-member rule). Move custom annotations into <code>metadata</code> rather than adding top-level fields. Unsupported fields exit <code>2</code> with no stdout in text or <code>--json</code> mode; diagnostics list supported names without echoing unknown names or values. This is a local configuration-integrity policy, not an Azure service schema, and does not certify that the chosen controls cover every release requirement <span class="ev-badge ev-arch">[Arch]</span>.</p><p>Latency values must also fit the verifier&#39;s finite floating-point range. Python can decode a JSON integer such as <code>10^400</code> even though formatting it as a latency would overflow; the kit now rejects that value before percentile evaluation or diagnostic formatting. An oversized <code>duration_ms</code> produces a field-specific <code>ARG001</code> failure and exit <code>1</code>, preserving other trace findings; an oversized <code>max_p95_ms</code> produces an invalid-acceptance-contract diagnostic and exit <code>2</code> before reading evidence. Neither diagnostic echoes the numeric value. Ordinary integers, fractional milliseconds, and large representable values remain supported. Offline self-tests cover both text and <code>--json</code> output, mixed trace findings, configuration-validation precedence, and large representable latency failures. This is a local numeric-processing boundary, not an Azure service limit or recommended latency SLO <span class="ev-badge ev-arch">[Arch]</span>.</p>',48))])}const x=r(p,[["render",u]]);export{b as __pageData,x as default};
